temas.css:
.th-grimm .logo{color:var(--ac)}
.th-grimm .b,.th-grimm .ch,.th-grimm .rc,.th-grimm .pn,.th-grimm .pc,.th-grimm .pill{border-radius:0}
.th-grimm .b{border-color:var(--ac);box-shadow:3px 3px 0 #000}
.th-grimm .b.on,.th-grimm .big,.th-grimm .ch.on{background:linear-gradient(#e0193a,#7d0a1c);color:#fff}
.th-grimm .rb{clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%);box-shadow:none}
.th-grimm .mp button{color:#e01b34;text-shadow:0 0 4px #000,0 0 2px #000;font-weight:900}
.th-grimm #mas{width:150%;right:-22%}
.th-grimm .wrap{position:relative;z-index:1}
body.th-grimm{background-image:radial-gradient(ellipse at 50% 112%,#4a0a18 0,transparent 62%),radial-gradient(var(--dot) 1.3px,transparent 1.6px);background-size:100% 100%,9px 9px;background-position:0 0,0 0;background-repeat:no-repeat,repeat}
body.th-grimm::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:0;opacity:.6;background-image:radial-gradient(circle,#ff4d63 0 1.6px,transparent 2.6px),radial-gradient(circle,#ff9a6a 0 1.2px,transparent 2.2px),radial-gradient(circle,#c41230 0 2.2px,transparent 3.4px);background-size:130px 170px,210px 260px,90px 120px;background-position:10px 20px,70px 90px,40px 60px}
body.th-grimm::after{content:"";position:fixed;inset:0;pointer-events:none;z-index:2;background:radial-gradient(ellipse at 50% 45%,transparent 52%,rgba(0,0,0,.65) 100%)}
.th-grimm .frame{border-color:var(--ac);box-shadow:inset 0 0 46px #c4123030}
.th-grimm .hd{border-bottom-color:var(--ac)}
.th-grimm .logo{text-shadow:0 0 14px #c41230,2px 2px 0 #000}
.th-grimm .vin{filter:drop-shadow(0 0 7px #c41230)}
.th-grimm .men{background:var(--ac)}
.th-grimm .men::after{background:var(--bg)}
.th-grimm .lup{background:var(--card);border-color:var(--ac);color:var(--ac2)}
.th-grimm .rc{border-color:#5a1a2c;box-shadow:0 0 0 1px #000}
.th-grimm .rc::before{opacity:.78}
.th-grimm .rc .n::before{content:'✦ ';color:var(--ac2)}
.th-grimm .rc.on{border-color:var(--ac2)}
.th-grimm .ch{border-color:#5a1a2c}
.th-grimm:not(.glow) #p #cov{border-color:var(--ac);box-shadow:0 0 0 2px #000,0 0 30px #c412309e}
.th-grimm #sk{border-radius:0}
.th-grimm #sk::-webkit-slider-thumb{width:20px;height:24px;border:0;border-radius:0;background:var(--ac2);clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
.th-grimm #sk::-moz-range-thumb{width:20px;height:24px;border:0;border-radius:0;background:var(--ac2);clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
.th-grimm .lyc{border-color:var(--ac)}
.th-grimm .side::before{content:"";position:absolute;right:-34%;bottom:4%;width:150%;height:42%;background:radial-gradient(closest-side,#c4123088,transparent);filter:blur(10px);pointer-events:none}
.th-grimm #mas{filter:drop-shadow(0 0 12px rgba(196,18,48,.75));transform-origin:50% 100%}
@keyframes g-ember{to{background-position:10px -150px,70px -170px,40px -60px}}
@keyframes g-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
@keyframes g-sway{0%,100%{transform:translateY(0) rotate(-1.6deg)}50%{transform:translateY(-14px) rotate(1.6deg)}}
@keyframes g-pulse{0%,100%{box-shadow:0 0 0 1px #000,0 0 7px #c41230,0 0 16px #c4123066}50%{box-shadow:0 0 0 1px #000,0 0 14px #ff4d63,0 0 30px #c41230aa}}
@keyframes g-breath{0%,100%{opacity:.55}50%{opacity:1}}
@media(prefers-reduced-motion:no-preference){
body.th-grimm::before{animation:g-ember 15s linear infinite}
.th-grimm #mas{animation:g-float 6s ease-in-out infinite}
.th-grimm.playing #mas{animation:g-sway 2.4s ease-in-out infinite}
.th-grimm .side::before{animation:g-breath 3.2s ease-in-out infinite}
.th-grimm .rc.on{animation:g-pulse 2.6s ease-in-out infinite}
.th-grimm .rc.on.cv{animation:pan 18s ease-in-out infinite alternate,g-pulse 2.6s ease-in-out infinite}
.th-grimm.playing .vin{filter:drop-shadow(0 0 12px #ff4d63)}
}

@property --h{syntax:'<number>';inherits:true;initial-value:0}
@keyframes rb-h{to{--h:360}}
@keyframes rb-bg{to{transform:translateY(-587px)}}
body.th-rainbow{background-image:none;background-color:#fff8e7}
.th-rainbow .wrap{position:relative;z-index:1}
body.th-rainbow::before{content:"";position:fixed;left:0;top:0;width:100%;height:calc(100% + 587px);z-index:0;pointer-events:none;background:url(tema-rainbow-fondo.jpg) 0 0/562.5px 587px repeat}
.th-rainbow .hd{background:var(--card)}
.th-rainbow .logo{background:linear-gradient(90deg,#ff2a2a,#ff9a00,#e8c800,#00b84a,#0099ff,#7a4dff,#ff2a9a);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(1.5px 1.5px 0 #000)}
.th-rainbow .vin{filter:drop-shadow(0 0 6px hsl(var(--h) 100% 55%))}
.th-rainbow .ch.on,.th-rainbow .big,.th-rainbow .b.on{background:linear-gradient(90deg,#ff5a5a,#ffa800,#33cc66,#1aa3ff,#8a5bff);color:#fff;text-shadow:0 1px 2px #0009}
.th-rainbow #cnt{background:#ffffffe6;border-radius:12px;padding:6px 12px;min-height:0;margin-bottom:12px;align-items:center;opacity:1}
.th-rainbow .em,.th-rainbow .ptabs+*>.sub{background:#ffffffe6;border-radius:12px;padding:8px 12px;opacity:1}
.th-rainbow .pnm{background:#ffffffe6;border-radius:16px;padding:10px 12px;border:2px solid var(--ink)}
.th-rainbow .rc.on{border-color:var(--ink);box-shadow:0 0 0 1px #000,0 0 10px 2px hsl(var(--h) 100% 55%),0 0 26px 7px hsl(calc(var(--h) + 120) 100% 55% / .6)}
.th-rainbow:not(.glow) #p #cov{box-shadow:0 0 0 2px #000,0 0 18px 4px hsl(var(--h) 100% 55%),0 0 40px 10px hsl(calc(var(--h) + 120) 100% 55% / .5)}
.th-rainbow #sk{background:linear-gradient(90deg,transparent var(--p,0%),var(--dot) var(--p,0%)),linear-gradient(90deg,#ff2a2a,#ff9a00,#ffe600,#00d84a,#00b7ff,#7a4dff,#ff2a9a)}
.th-rainbow #sk::-webkit-slider-thumb{background:hsl(var(--h) 100% 55%);border-color:#000}
.th-rainbow #sk::-moz-range-thumb{background:hsl(var(--h) 100% 55%);border-color:#000}
.th-rainbow #mfill{background:hsl(var(--h) 100% 55%)}
.th-rainbow .ptx{background:#ffffffe6;border-radius:14px;padding:8px 12px}
.th-rainbow .tm{background:#ffffffe6;border-radius:999px;padding:1px 12px}
.th-rainbow #s>.t{background:#ffffffe6;border-radius:12px;padding:8px 12px}
@media(prefers-reduced-motion:no-preference){body.th-rainbow{animation:rb-h 6s linear infinite}body.th-rainbow::before{animation:rb-bg 16s linear infinite}}
